```python
import random
import string

def render_grid(rows, cols):
    """
    Renders a grid of numbers and random letters.

    Args:
        rows (int): The number of rows in the grid.
        cols (int): The number of columns in the grid.

    Returns:
        None
    """
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                print('┌', end='')
            elif i == 0 and j == cols - 1:
                print('┤', end='')
            elif i == rows - 1 and j == 0:
                print('┐', end='')
            elif i == rows - 1 and j == cols - 1:
                print('┥', end='')
            elif j == 0 and i > 0 and i < rows - 1:
                print('|', end='')
            elif j > 0 and j < cols - 1:
                if i * cols + j < rows * cols / 2:
                    print(str(i * cols + j).zfill(len(str(rows * cols - 1))), end='')
                else:
                    print(random.choice(string.ascii_uppercase), end='')
            print(' ', end='', flush=True)
        print()

if __name__ == "__main__":
    render_grid(10, 10)
```

