class Game:
    """
    A simple text-based adventure game.

    Attributes:
        location (str): The current location in the game world.
        inventory (list): A list of items the player has collected.
    """

    def __init__(self):
        """
        Initialize the game with the player at the starting location.
        """
        self.location = "forest"
        self.inventory = []

    def describe_location(self):
        """
        Print a description of the current location.
        """
        if self.location == "forest":
            print("You are in a dense forest.")
        elif self.location == "cave":
            print("You are in a dark and damp cave.")
        else:
            print("You are somewhere else.")

    def move(self, direction):
        """
        Move the player in the specified direction.

        Args:
            direction (str): The direction to move (e.g., "north", "south", etc.).

        Returns:
            bool: True if the player successfully moves, False otherwise.
        """
        if self.location == "forest":
            if direction == "cave":
                self.location = "cave"
                return True
        elif self.location == "cave":
            if direction == "forest":
                self.location = "forest"
                return True
        return False

    def take_item(self, item):
        """
        Add the specified item to the player's inventory.

        Args:
            item (str): The item to take.

        Returns:
            bool: True if the item was successfully added to the inventory, False otherwise.
        """
        if item in ["torch", "map", "key"]:
            self.inventory.append(item)
            return True
        return False

    def use_item(self, item):
        """
        Use the specified item if the player has it.

        Args:
            item (str): The item to use.

        Returns:
            bool: True if the item was successfully used, False otherwise.
        """
        if item in self.inventory:
            if item == "torch":
                print("You use the torch to illuminate your way.")
                return True
            elif item == "map":
                print("You use the map to navigate the cave.")
                return True
            elif item == "key":
                print("You unlock a hidden door with the key.")
                return True
        return False


def main():
    """
    Create a Game instance and play the game.
    """
    game = Game()

    while True:
        game.describe_location()
        command = input("What do you want to do? ").lower().split()

        if command[0] == "go":
            if game.move(command[1]):
                continue
            else:
                print("You cannot move that way.")

        elif command[0] == "take":
            if game.take_item(command[1]):
                continue
            else:
                print("You cannot take that.")

        elif command[0] == "use":
            if game.use_item(command[1]):
                continue
            else:
                print("You do not have that.")

        elif command[0] == "quit":
            print("Thank you for playing!")
            break

        else:
            print("I don't understand that command.")


if __name__ == "__main__":
    main()
```

This code defines a `Game` class with methods for moving, taking items, and using items. The game's state is managed by the `location` and `inventory` attributes. The `main` function creates a `Game` instance and plays the game, allowing the player to interact with the game world.

To test the game, simply run the script in your terminal or command prompt. You can quit the game by typing "quit". The game will guide you through navigating a cave and collecting items to help you reach the end of the forest.

