def is_leap_year(year):
    """
    Check whether a given year is a leap year or not.

    Args:
        year (int): The year to check.

    Returns:
        bool: True if the year is a leap year, False otherwise.

    Raises:
        ValueError: If the year is less than 1752, as the Gregorian calendar
                    was not universally adopted until 1752.
    """
    if year < 1752:
        raise ValueError("Year must be 1752 or later for Gregorian calendar.")

    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    else:
        return False
