class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class Tree:
    def __init__(self):
        self.root = None

    def insert(self, val):
        """
        Inserts a new node with the given value into the tree.

        Args:
            val: The value to be inserted.

        Returns:
            The root node of the modified tree.
        """
        if self.root is None:
            self.root = TreeNode(val)
        else:
            self._insert_recursive(self.root, val)
        return self.root

    def _insert_recursive(self, node, val):
        """
        Recursively inserts a new node with the given value into the tree.

        Args:
            node: The current node being processed.
            val: The value to be inserted.
        """
        if val < node.val:
            if node.left is None:
                node.left = TreeNode(val)
            else:
                self._insert_recursive(node.left, val)
        else:
            if node.right is None:
                node.right = TreeNode(val)
            else:
                self._insert_recursive(node.right, val)

    def inorder_traversal(self):
        """
        Performs an inorder traversal of the tree and returns the values in a list.

        Returns:
            A list of the values in the tree in ascending order.
        """
        return self._inorder_traversal_recursive(self.root, [])

    def _inorder_traversal_recursive(self, node, result):
        """
        Recursively performs an inorder traversal of the tree and appends the values to the result list.

        Args:
            node: The current node being processed.
            result: The list to which the values will be appended.
        """
        if node is not None:
            self._inorder_traversal_recursive(node.left, result)
            result.append(node.val)
            self._inorder_traversal_recursive(node.right, result)
