class BinarySearchTree:
    """A binary search tree."""

    def __init__(self):
        """Initializes an empty binary search tree."""
        self.root = None

    def insert(self, value):
        """Inserts a new value into the tree, maintaining the binary search tree property."""
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, node, value):
        """A recursive helper function for inserting a new value into the tree."""
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)

    def search(self, value):
        """Returns True if the given value is present in the tree, and False otherwise."""
        return self._search_recursive(self.root, value)

    def _search_recursive(self, node, value):
        """A recursive helper function for searching for a value in the tree."""
        if node is None or node.value == value:
            return node is not None
        elif value < node.value:
            return self._search_recursive(node.left, value)
        else:
            return self._search_recursive(node.right, value)

    def inorder_traversal(self):
        """Returns a list of the values in the tree in ascending order."""
        result = []
        self._inorder_traversal_recursive(self.root, result)
        return result

    def _inorder_traversal_recursive(self, node, result):
        """A recursive helper function for performing an inorder traversal of the tree."""
